/**
 * A scoped port of `argparse.ArgumentParser` covering the exact behaviour the
 * reference program exhibits: two optionals (`-h/--help` and a required
 * `--a A`) and no positionals.
 *
 * The token-classification and option-consumption logic follows CPython's
 * `_parse_optional`, `_get_option_tuples` and `_parse_known_args`, which is why
 * the corner cases line up:
 *
 *   `--a -5`      -> value `-5`   (negative-number matcher)
 *   `--a -.5`     -> value `-.5`
 *   `--a -1e5`    -> error, `-1e5` reads as an unknown option
 *   `--a -- x`    -> error, `--` is never accepted as an option's value
 *   `--h`         -> help, unambiguous abbreviation of `--help`
 *   `-ha`         -> help runs, then `-a` is stashed as unrecognised
 *   `--=x`        -> ambiguous option: could match --help, --a
 *   `--help=x`    -> argument -h/--help: ignored explicit argument 'x'
 */

import * as path from 'node:path';

import { ACTION_HELP, ACTION_STORE, createHelpAction, createStoreAction } from './actions.mjs';
import { ArgumentError, SystemExit } from './errors.mjs';
import { HelpFormatter } from './formatter.mjs';
import { writeStderr, writeStdout } from '../runtime/stdio.mjs';

/** `ArgumentParser._negative_number_matcher`. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** `os.path.basename(sys.argv[0])`, the default `prog`. */
function defaultProg() {
  const script = process.argv[1];
  if (script === undefined) return '';
  return path.basename(script);
}

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog === undefined ? defaultProg() : prog;
    this.prefixChars = '-';
    this.allowAbbrev = true;
    /** @type {import('./actions.mjs').Action[]} */
    this.actions = [];
    /** Insertion-ordered, exactly like `_option_string_actions`. */
    this.optionStringActions = new Map();
    this.hasNegativeNumberOptionals = false;

    this._addAction(createHelpAction());
  }

  /** `parser.add_argument('--a', type=str, required=True)`. */
  addArgument(optionString, { required = false, help = null } = {}) {
    const dest = optionString.replace(/^--?/, '').replace(/-/g, '_');
    this._addAction(createStoreAction([optionString], dest, { required, help }));
  }

  _addAction(action) {
    this.actions.push(action);
    for (const optionString of action.optionStrings) {
      this.optionStringActions.set(optionString, action);
      if (NEGATIVE_NUMBER.test(optionString)) this.hasNegativeNumberOptionals = true;
    }
  }

  _formatter() {
    return new HelpFormatter(this.prog, this.actions);
  }

  formatUsage() {
    return this._formatter().formatUsage();
  }

  formatHelp() {
    return this._formatter().formatHelp();
  }

  printUsage(stream) {
    stream(this.formatUsage());
  }

  printHelp() {
    writeStdout(this.formatHelp());
  }

  /** `parser.exit(status, message)`. */
  exit(status = 0, message = null) {
    if (message !== null) writeStderr(message);
    throw new SystemExit(status);
  }

  /** `parser.error(message)` — usage to stderr, then exit status 2. */
  error(message) {
    this.printUsage(writeStderr);
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  /** `parser.parse_args()`. */
  parseArgs(argStrings) {
    const { namespace, extras } = this.parseKnownArgs(argStrings);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /** `parser.parse_known_args()`. */
  parseKnownArgs(argStrings) {
    const namespace = Object.create(null);
    for (const action of this.actions) {
      if (action.kind === ACTION_STORE) namespace[action.dest] = null;
    }

    try {
      return this._parseKnownArgs(argStrings, namespace);
    } catch (error) {
      if (error instanceof ArgumentError) {
        this.error(error.toDisplayString());
      }
      throw error;
    }
  }

  _parseKnownArgs(argStrings, namespace) {
    // ---- Pass 1: classify every token as 'O' (option), 'A' (value) or '-'.
    const pattern = [];
    /** @type {Map<number, object>} */
    const optionTuples = new Map();
    let afterDoubleDash = false;

    for (let index = 0; index < argStrings.length; index += 1) {
      const argString = argStrings[index];
      if (afterDoubleDash) {
        pattern.push('A');
        continue;
      }
      if (argString === '--') {
        afterDoubleDash = true;
        pattern.push('-');
        continue;
      }
      const optionTuple = this._parseOptional(argString);
      if (optionTuple === null) {
        pattern.push('A');
      } else {
        optionTuples.set(index, optionTuple);
        pattern.push('O');
      }
    }

    // ---- Pass 2: consume options; anything left over is "unrecognized".
    // There are no positional actions, so every non-option token that an
    // option does not swallow becomes an extra.
    const extras = [];
    const seenActions = new Set();
    let startIndex = 0;

    while (startIndex < argStrings.length) {
      if (pattern[startIndex] !== 'O') {
        extras.push(argStrings[startIndex]);
        startIndex += 1;
        continue;
      }
      startIndex = this._consumeOptional({
        startIndex,
        argStrings,
        pattern,
        optionTuples,
        namespace,
        seenActions,
        extras,
      });
    }

    const missing = this.actions
      .filter((action) => action.required && !seenActions.has(action))
      .map((action) => action.optionStrings.join('/'));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return { namespace, extras };
  }

  /** `consume_optional` from `_parse_known_args`. */
  _consumeOptional(context) {
    const { startIndex, argStrings, pattern, optionTuples, extras } = context;
    let { action, optionString, sep, explicitArg } = optionTuples.get(startIndex);

    /** @type {Array<{action: object, args: string[], optionString: string}>} */
    const actionTuples = [];
    let stop = startIndex + 1;

    for (;;) {
      if (action === null) {
        extras.push(optionString);
        return startIndex + 1;
      }

      if (explicitArg !== null && explicitArg !== undefined) {
        const argCount = this._matchArgument(action, 'A');
        const chars = this.prefixChars;

        if (argCount === 0 && !chars.includes(optionString[1]) && explicitArg !== '') {
          // A single-dash flag with a tail: try to read more flags out of it.
          if (sep || chars.includes(explicitArg[0])) {
            throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
          }
          actionTuples.push({ action, args: [], optionString });
          const char = optionString[0];
          optionString = char + explicitArg[0];
          const next = this.optionStringActions.get(optionString);
          if (next !== undefined) {
            action = next;
            explicitArg = explicitArg.slice(1);
            if (explicitArg === '') {
              sep = null;
              explicitArg = null;
            } else if (explicitArg[0] === '=') {
              sep = '=';
              explicitArg = explicitArg.slice(1);
            } else {
              sep = '';
            }
          } else {
            extras.push(char + explicitArg);
            stop = startIndex + 1;
            break;
          }
        } else if (argCount === 1) {
          stop = startIndex + 1;
          actionTuples.push({ action, args: [explicitArg], optionString });
          break;
        } else {
          throw new ArgumentError(action, `ignored explicit argument ${pyRepr(explicitArg)}`);
        }
      } else {
        const start = startIndex + 1;
        const selectedPattern = pattern.slice(start).join('');
        const argCount = this._matchArgument(action, selectedPattern);
        stop = start + argCount;
        actionTuples.push({ action, args: argStrings.slice(start, stop), optionString });
        break;
      }
    }

    for (const tuple of actionTuples) {
      this._takeAction(tuple.action, tuple.args, context);
    }
    return stop;
  }

  /** `take_action` — run the action and record it for the `required` check. */
  _takeAction(action, args, context) {
    context.seenActions.add(action);
    if (action.kind === ACTION_HELP) {
      this.printHelp();
      this.exit(0);
      return;
    }
    // `type=str` is the identity conversion.
    context.namespace[action.dest] = args[0];
  }

  /**
   * `_match_argument`: how many of the following tokens this action consumes.
   * The `-*` wildcards are stripped for optionals, which is precisely why a
   * `--` can never satisfy `--a`.
   */
  _matchArgument(action, patternSlice) {
    let nargsPattern = action.nargs === 0 ? '(-*-*)' : '(-*A-*)';
    if (action.optionStrings.length > 0) {
      nargsPattern = nargsPattern.split('-*').join('').split('-').join('');
    }
    const match = new RegExp(`^${nargsPattern}`).exec(patternSlice);
    if (match === null) {
      const message =
        action.nargs === null ? 'expected one argument' : `expected ${action.nargs} arguments`;
      throw new ArgumentError(action, message);
    }
    return match[1].length;
  }

  /**
   * `_parse_optional`: decide whether a token is an option, and if so which.
   * Returns `null` for "this is a value", or a tuple whose `action` is `null`
   * for "this looks like an option but I do not know it".
   */
  _parseOptional(argString) {
    if (argString === '') return null;
    if (!this.prefixChars.includes(argString[0])) return null;

    const exact = this.optionStringActions.get(argString);
    if (exact !== undefined) {
      return { action: exact, optionString: argString, sep: null, explicitArg: null };
    }

    if (argString.length === 1) return null;

    const equalsAt = argString.indexOf('=');
    if (equalsAt !== -1) {
      const head = argString.slice(0, equalsAt);
      const tail = argString.slice(equalsAt + 1);
      const action = this.optionStringActions.get(head);
      if (action !== undefined) {
        return { action, optionString: head, sep: '=', explicitArg: tail };
      }
    }

    const candidates = this._getOptionTuples(argString);
    if (candidates.length > 1) {
      const matches = candidates.map((candidate) => candidate.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (candidates.length === 1) {
      return candidates[0];
    }

    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, sep: null, explicitArg: null };
  }

  /** `_get_option_tuples`: abbreviation and joined-short-option matching. */
  _getOptionTuples(argString) {
    const chars = this.prefixChars;
    const result = [];

    if (chars.includes(argString[0]) && chars.includes(argString[1])) {
      if (!this.allowAbbrev) return result;
      const equalsAt = argString.indexOf('=');
      const optionPrefix = equalsAt === -1 ? argString : argString.slice(0, equalsAt);
      const sep = equalsAt === -1 ? null : '=';
      const explicitArg = equalsAt === -1 ? null : argString.slice(equalsAt + 1);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, sep, explicitArg });
        }
      }
      return result;
    }

    // Single-dash token: `-hVALUE` style.
    const shortPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [optionString, action] of this.optionStringActions) {
      if (optionString === shortPrefix) {
        result.push({ action, optionString, sep: '', explicitArg: shortExplicitArg });
      } else if (optionString.startsWith(argString)) {
        result.push({ action, optionString, sep: null, explicitArg: null });
      }
    }
    return result;
  }
}

/** `%r` for the short strings that appear in argparse messages. */
function pyRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let body = '';
  for (const ch of text) {
    if (ch === quote || ch === '\\') body += `\\${ch}`;
    else body += ch;
  }
  return `${quote}${body}${quote}`;
}

